mapper.select:
SELECT urp.user_id AS "userId", uli.email, uli.phone, uli.status, urp.current_score AS "currentScore", urp.risk_level AS "riskLevel", urp.lock_count AS "lockCount", urp.lock_reason AS "lockReason", urp.lock_until AS "lockUntil", urp.last_login_at AS "lastLoginAt", urp.updated_at AS "updatedAt" FROM user_risk_profile urp LEFT JOIN user_login_identity uli ON uli.user_id = urp.user_id
AND urp.user_id = #{userId}
AND LOWER(uli.email) LIKE #{emailPattern}
AND uli.phone LIKE #{phonePattern}
AND uli.status = #{status}
AND urp.risk_level = #{riskLevel}
ORDER BY urp.current_score ASC, urp.updated_at DESC NULLS LAST, urp.user_id DESC

mapper.update:

UPDATE user_risk_profile
SET current_score = #{scoreAfter},
    risk_level = #{riskLevelAfter},
    behavior_score_delta = behavior_score_delta + #{scoreDelta},
    last_risk_penalty_at = CASE
        WHEN #{scoreDelta} < 0 THEN #{updatedAt}
        ELSE last_risk_penalty_at
    END,
    updated_at = #{updatedAt}
WHERE user_id = #{userId}

mapper.select:
SELECT s.id, s.user_id AS "userId", s.email, s.phone, uli.status, s.is_deleted AS "deleted", ( s.is_deleted = FALSE AND s.restored_at IS NULL AND s.deleted_at IS NOT NULL AND s.deleted_at >= #{cutoff} ) AS "restorable", s.deletion_reason AS "deletionReason", s.deleted_at AS "deletedAt", s.created_at AS "createdAt", s.restored_at AS "restoredAt", s.restored_by AS "restoredBy", s.restore_reason AS "restoreReason" FROM user_account_self_deletion s LEFT JOIN user_login_identity uli ON uli.user_id = s.user_id
AND s.user_id = #{userId}
AND LOWER(s.email) LIKE #{emailPattern}
AND s.phone LIKE #{phonePattern}
AND s.is_deleted = FALSE AND s.restored_at IS NULL AND s.deleted_at IS NOT NULL AND s.deleted_at >= #{cutoff}
AND s.is_deleted = FALSE AND s.restored_at IS NULL AND s.deleted_at IS NOT NULL AND s.deleted_at < #{cutoff}
AND s.is_deleted = TRUE
AND s.restored_at IS NOT NULL
ORDER BY s.deleted_at DESC NULLS LAST, s.created_at DESC, s.id DESC

mapper.update:

UPDATE user_login_identity
SET status = 'ACTIVE',
    updated_at = #{updatedAt}
WHERE user_id = #{userId}
  AND status = 'DISABLED'


UPDATE user_account_self_deletion
SET restored_at = #{restoredAt},
    restored_by = #{restoredBy},
    restore_reason = #{restoreReason}
WHERE id = #{id}
  AND is_deleted = FALSE
  AND restored_at IS NULL
  AND deleted_at IS NOT NULL
  AND deleted_at >= #{cutoff}

mapper.select:
SELECT t.id, t.user_id AS "userId", t.email, t.phone, uli.status, COALESCE(urp.current_score, 0) AS "currentScore", urp.risk_level AS "riskLevel", COALESCE(urp.lock_count, 0) AS "lockCount", t.termination_reason AS "terminationReason", t.terminated_at AS "terminatedAt", t.created_at AS "createdAt" FROM user_risk_account_termination t LEFT JOIN user_login_identity uli ON uli.user_id = t.user_id LEFT JOIN user_risk_profile urp ON urp.user_id = t.user_id
AND t.user_id = #{userId}
AND LOWER(t.email) LIKE #{emailPattern}
AND t.phone LIKE #{phonePattern}
ORDER BY t.terminated_at DESC, t.id DESC
